import{_ as d}from"./chunks/maintenance-pwr.pc.ko.DU4C6rG6.js";import{_ as o}from"./chunks/settings-cal.pc.ko.BDoJOykj.js";import{_ as c,o as t,c as a,a5 as i}from"./chunks/framework.BYXPg_yw.js";const r="/RBQ/nightly/images/app/settings-chk.pc.ko.png",l="/RBQ/nightly/images/app/maintenance-vision.pc.ko.png",n="/RBQ/nightly/images/app/maintenance-ini.pc.ko.png",S=JSON.parse('{"title":"정비","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/maintenance.md","filePath":"ko/manual/gui/maintenance.md","lastUpdated":1793350928000}'),h={name:"ko/manual/gui/maintenance.md"};function p(s,e,m,b,u,P){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="정비" tabindex="-1">정비 <a class="header-anchor" href="#정비" aria-label="Permalink to &quot;정비&quot;">​</a></h1><p>허브의 <code>정비</code> 타일로 엽니다. 타일은 모든 사용자에게 보이고 로봇이 연결되지 않아도 열립니다. 로봇에 작용하는 섹션은 연결돼 있어야 동작합니다. 섹션은 화면 위쪽에 칩으로 늘어섭니다.</p><ul><li><strong>모든 사용자:</strong> <code>전원 / 시스템</code>, <code>캘리브레이션</code>, <code>로봇 점검</code>, <code>PTZ 점검</code>(PTZ 가 달린 로봇에서만). 원격 점검은 <code>로봇 점검</code> 맨 아래에 있습니다.</li><li><strong><a href="/RBQ/nightly/ko/manual/gui/developer-mode.html">개발자 모드</a> 전용:</strong> <code>비전</code>, <code>설정 파일</code>, 그리고 팔이 있는 로봇에서만 보이는 <code>팔</code>. 칩 이름 뒤에 <code>Lv2</code> 꼬리표가 붙습니다.</li></ul><p>소프트웨어·펌웨어 업데이트는 따로 화면이 있습니다. <a href="/RBQ/nightly/ko/manual/gui/software-update.html">업데이트</a>를 보세요.</p><h2 id="power" tabindex="-1">전원 / 시스템 <a class="header-anchor" href="#power" aria-label="Permalink to &quot;전원 / 시스템 {#power}&quot;">​</a></h2><p><img src="'+d+'" alt="전원 / 시스템 섹션"></p><p>앱 내 시뮬레이터를 고른 동안이나 다른 기기가 조종 중일 때는 <code>전원 / 시스템</code> 칩이 흐리게 표시되고 열리지 않습니다. 화면은 캘리브레이션 탭처럼 섹션으로 나뉩니다: <code>상단 포트</code>, <code>전/후방</code>, <code>카메라</code>, <code>내부</code>, <code>로봇 PC</code>, <code>비전</code>. CAN-FD 기체에는 <code>내부</code> 다음에 <code>하단 상태 LED (IF 보드)</code>, <code>상단 LED (TOP 보드)</code>, <code>입력 포트 · 배터리 · 온도</code>가 더 있습니다. 토글과 버튼은 로봇이 보고한 실제 상태를 표시하며, 상태를 받기 전에는 비활성화됩니다. 반영에 1초 정도 걸릴 수 있습니다.</p><p>전원 섹션의 토글은 한 번 탭으로 바뀝니다. 다만 <code>12V 포트</code>를 끌 때는 무엇이 물렸는지 앱이 알 수 없어 <code>정말 끌까요?</code>를 먼저 묻습니다 — 연결된 장비의 전원이 꺼지고, 통신장비가 연결되어 있다면 앱과의 연결이 끊길 수 있다고 안내합니다. <code>끄기</code> / <code>켜기</code> 버튼이 있는 행은 <code>정말 끌까요?</code> / <code>정말 켤까요?</code>에서 한 번 더 확정해야 바뀝니다. 확인은 매번 묻습니다.</p><table tabindex="0"><thead><tr><th>섹션</th><th>비 CAN-FD 기체</th><th>CAN-FD 기체</th></tr></thead><tbody><tr><td><code>상단 포트</code></td><td><code>12V 포트 1</code>~<code>4</code>(토글, 끌 때 확인), <code>ARM · ADDON (48V)</code>, <code>EXTERN (48V)</code></td><td><code>12V 포트 1</code>~<code>4</code>(토글, 끌 때 확인), <code>ARM · ADDON (48V)</code></td></tr><tr><td><code>전/후방</code></td><td><code>전/후방 12V</code> — 전방·후방을 함께 켜고 끕니다(토글)</td><td><code>전방 12V</code>, <code>후방 12V</code>(토글)</td></tr><tr><td><code>카메라</code></td><td><code>카메라 (5V)</code> — 카메라 전체, <code>오디오·USB 허브 (5V)</code></td><td>카메라 0~5, <code>사이드 카메라 좌 (USB)</code>, <code>사이드 카메라 우 (USB)</code> — 카메라마다, <code>전방 허브 리셋</code>, <code>후방 허브 리셋</code></td></tr><tr><td><code>내부</code></td><td><code>스피커 앰프 (12V)</code>(토글), <code>User PC (12V)</code>, <code>LEGS (48V 구동)</code></td><td><code>스피커 앰프</code>(토글), <code>LEGS (48V 구동)</code>, <code>PDU (48V 배터리 레일)</code>(표시만)</td></tr></tbody></table><p><code>상단 포트</code> 옆 <code>? 도움말</code>은 상단 포트 위치를 그림으로 보여 줄 창입니다. 그림은 추후 추가될 예정입니다. 12V 포트는 무엇을 물리느냐가 로봇마다 달라 번호로만 부릅니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>ARM · ADDON (48V)</code>는 팔과 애드온이 PDU 포트 하나를 함께 씁니다. 이 레일을 끄면 팔 전원도 함께 나가므로 팔이 정지 상태인지 먼저 확인하세요. 카메라·<code>User PC (12V)</code>를 끄면 영상과 오디오가 끊깁니다.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>LEGS (48V 구동)</code>을 끄면 로봇이 주저앉습니다. 로봇이 서 있지 않을 때(앉음·제어 꺼짐·낙상)만 끌 수 있으며, 그 외에는 행이 차단됩니다. <code>로봇 PC</code>의 <code>로봇 서비스 재시작</code> — <code>로봇 서비스 재시작</code> → <code>로봇 서비스를 재시작할까요?</code> → <code>로봇 서비스 재시작</code> — 은 PC를 켜 둔 채 로봇 소프트웨어만 다시 시작합니다. 제어권을 쥔 기기에서만 됩니다(아니면 <code>재시작 요청 실패</code> — 먼저 제어권을 가져오세요. <a href="/RBQ/nightly/ko/manual/gui/control-home.html">제어 홈</a> 참고). <code>로봇 PC 재부팅</code> — <code>로봇 PC 재부팅</code> → <code>로봇 PC를 재부팅할까요?</code> → <code>로봇 PC 재부팅</code> — 은 로봇 PC를 재시작합니다. 그 서비스 없이 설치된 로봇에서는 <code>재시작 요청 실패</code>가 뜨니 <code>로봇 PC 재부팅</code>을 쓰세요. 어느 쪽이든 그동안 로봇은 모터 전원을 잃고 앱 연결이 끊깁니다. 두 조작 모두 로봇을 바닥에 앉힌 뒤에 하세요.</p></div><p>CAN-FD 기체에서는 각 행에 실측 상태·전압·전류가 나오고, <code>입력 포트 · 배터리 · 온도</code> 섹션에 충전 입력, 배터리 두 팩, 보드 온도가 나옵니다.</p><p><code>카메라</code> 섹션의 <code>전방 허브 리셋</code>·<code>후방 허브 리셋</code> — <code>리셋</code> → <code>허브를 리셋할까요?</code> → <code>리셋</code> — 은 사이드 보드가 USB 허브를 다시 시작합니다. 그 보드의 카메라 셋(전방 <code>카메라 0 · 1 · 4</code>, 후방 <code>카메라 2 · 3 · 5</code>) 영상이 잠시 끊겼다가 다시 붙고, 결과는 행 아래에 나옵니다. hw 1.1.0.1 사이드 보드에서만 되며, 그 전 보드는 <code>이 사이드 보드는 허브 SMBus 를 지원하지 않습니다 — hw 1.1.0.1 보드만 됩니다</code>가 나옵니다.</p><p><code>비전</code> 섹션의 <code>VISION RESET</code> → <code>리셋</code>은 Handler가 <code>HAL</code>, <code>Streamer</code> 등 비전 데몬을 모두 다시 시작합니다. HAL이 시작하면서 카메라 전원을 껐다 켜므로, 카메라와 Streamer가 다시 올라올 때까지 영상이 끊깁니다. 버튼은 <code>리셋 중…</code>으로 바뀌어 약 8초 동안 비활성화됩니다.</p><h3 id="led-bottom" tabindex="-1">하단 상태 LED <a class="header-anchor" href="#led-bottom" aria-label="Permalink to &quot;하단 상태 LED {#led-bottom}&quot;">​</a></h3><p>CAN-FD 기체에서는 <code>내부</code> 섹션 아래에 <code>하단 상태 LED (IF 보드)</code>가 나옵니다. 몸체 아래 상태 LED 두 개가 <code>오른쪽 LED</code>, <code>왼쪽 LED</code> 한 줄씩 나오고, 줄마다 지금 설정과 소비 전력(W), 실제로 나가는 색이 보입니다. <code>설정</code>을 누르면 로봇이 알려 준 값으로 채워진 창이 뜹니다. <code>추천 설정</code>에서 <code>꺼 두기</code>나 RBQ에 쓰기로 정한 값을 고르면 되고, 창에 <code>지금 설정</code>도 함께 나옵니다. <code>반대쪽 LED에도 같은 값 적용</code>을 켜면 두 LED를 한 번에 바꿉니다. <code>적용</code>을 누르면 설정을 보낸 뒤 로봇에서 다시 읽어 확인합니다. <code>적용했습니다 — 로봇 값과 일치합니다</code>가 뜨면 LED가 받은 것입니다. <code>다시 읽기</code>는 로봇의 값으로 창을 다시 채웁니다.</p><p>LED 전력은 IF 보드가 스스로 제한합니다(순간 20 W, 지속 10.5 W). 그래서 밝게 설정하면 넣은 값보다 어둡게 나올 수 있고, 그때 줄에 <code>제한 중</code>이 뜹니다. 로봇에서 값을 읽지 못하면 <code>읽지 못함</code>과 함께 이 기기가 마지막으로 읽었거나 보낸 값을 보여 줍니다. IF 보드가 재부팅한 직후에는 설정이 들어올 때까지 <code>설정 없음 — IF가 재부팅한 뒤 아직 설정을 받지 못했습니다</code>로 나옵니다. 로봇 소프트웨어가 이 기능보다 오래됐으면 줄에 <code>로봇 소프트웨어에 이 기능이 없습니다. 업데이트가 필요합니다</code>가 뜹니다. IF 보드 펌웨어가 오래됐으면 줄에 지금 버전과 필요한 버전이 함께 나오고(예: <code>IF 펌웨어 업데이트가 필요합니다 — 지금 261003, 261005 이상이어야 합니다</code>), 보드를 업데이트할 때까지 <code>적용</code>이 잠깁니다.</p><p>그 아래 <code>상단 LED (TOP 보드)</code>에는 <code>램프 테스트</code> 한 줄이 있습니다. <code>램프 테스트</code>를 누르면 상단 패널 LED 7개가 지금 무엇을 보이고 있든 빨강 → 초록 → 파랑으로 1.6초 켜지고, 버튼 옆 점 7개가 같은 색을 따라가 실제 LED와 맞대 볼 수 있습니다. 앱은 요청을 보냈다는 것까지만 알기 때문에(<code>보냈습니다 — 상단 LED 7개가 오른쪽 점과 같은 색으로 바뀌는지 보세요</code>) 결과는 눈으로 확인합니다. TOP 보드 펌웨어가 261006보다 오래됐으면 TOP이 켜진 지 10초가 지나야 돕니다. 로봇 소프트웨어가 이 기능보다 오래됐으면 줄에 <code>로봇 소프트웨어에 이 기능이 없습니다. 업데이트가 필요합니다</code>가 뜹니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#what-changes">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h2 id="calibration" tabindex="-1">캘리브레이션 <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;캘리브레이션 {#calibration}&quot;">​</a></h2><p><img src="'+o+'" alt="캘리브레이션 섹션"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>여기의 모든 보정은 로봇을 평지에 <strong>정지</strong> 상태로 두고 실행해야 합니다. 로봇이 걷고 있거나 넘어졌거나 상태를 보내지 않으면 IMU·ZMP 행이 막힙니다. 명령을 보내기 전에는 <code>보정을 실행할까요?</code> 확인이 먼저 뜹니다. 관절 홈포즈 세팅은 확인 창을 따로 씁니다. 보정이 끝날 때까지 로봇을 건드리지 마세요.</p></div><h3 id="imu-캘리브레이션" tabindex="-1">IMU 캘리브레이션 <a class="header-anchor" href="#imu-캘리브레이션" aria-label="Permalink to &quot;IMU 캘리브레이션&quot;">​</a></h3><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>가속도계 보정 (ACC)</code></td><td>가속도계 드리프트를 현장에서 보정합니다. <strong>로봇을 앉힌 상태로</strong> 평지에 두고 실행하며, 약 2초 동안 중력 크기를 평균 내 보정계수를 저장합니다.</td></tr><tr><td><code>IMU 롤/피치 영점</code></td><td>현재 자세를 수평 기준으로 삼습니다. 약 0.5초 — 기울어진 상태로 실행하면 이후 제어가 전부 틀어집니다.</td></tr><tr><td><code>자이로 바이어스 보정</code></td><td>IMU를 리셋하고 값이 자리 잡기를 기다린 뒤 자이로 값을 다시 측정합니다. 약 5초, <strong>로봇을 앉힌 상태로</strong> 실행합니다. 끝나면 세 축의 값과 각 축이 허용치 안에 드는지를 알려 줍니다. 그래도 편차가 허용치를 넘으면 로봇을 완전히 멈춰 둔 채로 다시 실행하십시오.</td></tr></tbody></table><p><code>실행</code>을 누른 뒤 대화상자에서 <code>실행</code>으로 확정합니다. 막혀 있으면 이유를 알려 주고, 앱이 직접 풀 수 있는 것이면 <code>실행</code> 옆에 버튼이 하나 생깁니다 — 앉아야 하면 <code>앉기</code>, 서야 하면 <code>서기</code>, 제어가 꺼져 있으면 <code>자동 기동</code>입니다(이 버튼은 확인 창이 먼저 뜹니다). 넘어졌거나 도킹 중이거나 상태가 오지 않을 때는 버튼이 나오지 않습니다.</p><p><code>IMU 롤/피치 영점</code>은 확인 창의 수평계 아래에 현재 롤·피치를 보여 주고, 실행하는 동안 진행 창이 뜹니다. 롤·피치가 모두 1° 안으로 들어왔을 때만 <code>성공</code>으로 끝나고, 로봇이 아직 기울어 있으면 <code>영점이 반영되지 않았을 수 있습니다</code> 가 대신 뜹니다 — 평지에 두고 다시 실행하십시오.</p><h3 id="무게-중심-보정-zmp" tabindex="-1">무게 중심 보정 (ZMP) <a class="header-anchor" href="#무게-중심-보정-zmp" aria-label="Permalink to &quot;무게 중심 보정 (ZMP)&quot;">​</a></h3><p><code>무게 중심 오프셋 자동 보정</code>은 무게중심 오프셋을 자동으로 찾습니다. 로봇이 평지에서 STAND 상태여야 합니다. 다리를 나란히 맞추려고 한 걸음 걸은 뒤, 수렴할 때까지 최대 60초가 걸립니다. 오프셋이 수렴하면 로봇이 스스로 저장하고 STAND로 돌아옵니다. 패널에 진행 상황과 완료 메시지가 표시됩니다.</p><h3 id="관절-캘리브레이션" tabindex="-1">관절 캘리브레이션 <a class="header-anchor" href="#관절-캘리브레이션" aria-label="Permalink to &quot;관절 캘리브레이션&quot;">​</a></h3><p>다리 관절의 영점·오프셋을 다시 잡습니다. 로봇을 <strong>앉힌 상태</strong>로 실행합니다.</p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>관절 홈포즈 세팅</code></td><td>치구로 홈 자세를 고정한 뒤 그 자세를 관절 영점으로 저장 — 다리 4개</td></tr><tr><td><code>모터 캘리브레이션</code></td><td>관절 하나의 모터 캘리브레이션 기준을 제자리에서 다시 잡음 — 다리 4개의 관절마다 버튼이 있는 팝업</td></tr></tbody></table><p><code>관절 홈포즈 세팅</code>을 누르면 창이 둘 열립니다. 먼저 고지(<em>관절 영점을 다시 쓰는 조작입니다 — 치구가 없거나 자세가 어긋난 상태로 실행하면 로봇이 잘못된 영점으로 기동합니다</em>), 그다음 다리별 화면입니다. 그 화면에서 관절 카드를 누르면 그 관절이 왼쪽 3D 뷰에서 목표 자세까지 움직입니다. 치구를 끼워 그 자세를 만든 뒤 그 카드의 <code>LEG{n} - {g} 홈포즈 저장</code>을 누릅니다. 롤 카드와 피치·무릎 카드에 버튼이 따로 있습니다. 영점을 쓰는 순간 제어가 꺼지므로(BOARD_RESET) 로봇을 먼저 앉히십시오. 서 있으면 그대로 주저앉습니다. 치구가 필요합니다.</p><p>모터 보드와 통신이 없으면 행이 막히고 <em>모터 보드와 통신이 없습니다 — 48V 구동(LEGS) 전원을 켠 뒤 다시 실행하세요.</em> 가 뜹니다. 그 레일은 이 페이지의 <a href="#power">전원 / 시스템</a>에 있습니다.</p><p>롤 관절은 마법사에서 기준을 고릅니다. <code>리밋</code>은 종전처럼 안쪽 리밋에 갖다 대고 잡고, <code>수평계 0°</code>는 몸통이 수평인지 확인한 뒤 수평계로 관절을 0°에 맞추고, 영점을 그에 맞게 옮깁니다. 두 기준 모두 제어를 끕니다. 닫을 때 <code>자동 기동</code> 버튼으로 바로 다시 기동할 수 있습니다. 보정량이 9° 이상이면 로봇이 거부하고, 먼저 리밋에 대고 홈을 잡으라고 안내합니다.</p><p><code>모터 캘리브레이션</code>을 누르면 위에서 본 로봇 그림 둘레에 다리 넷이 놓인 창이 열리고, 다리마다 <code>Roll</code>·<code>Pitch</code>·<code>Knee</code> 버튼이 있습니다. 버튼을 누르면 그 관절이 바로 캘리브레이션됩니다. 확인 창은 따로 없습니다. 보드가 그 관절을 잠깐 멈추고 회전자를 붙잡아 새 기준을 저장한 뒤 다시 켜므로 영점은 그대로이고 재기동도 필요 없습니다. 로봇이 앉은 상태여야 합니다(서 있으면 <code>앉기</code> 버튼이 먼저 나옵니다). 끝나면 버튼에 <code>완료</code>가 뜨고, 보드가 거절했거나 모터 펌웨어가 지원하지 않으면 <code>거부</code>·<code>무응답</code>이 뜹니다. 한 번에 관절 하나씩 실행하고, 진행 중에는 로봇을 건드리지 마세요.</p><h3 id="camera-check" tabindex="-1">카메라 점검 · 보정 <a class="header-anchor" href="#camera-check" aria-label="Permalink to &quot;카메라 점검 · 보정 {#camera-check}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>카메라 기본 검사</code></td><td>카메라 6대의 실시간 화면과 FPS 를 한 화면에 띄웁니다. 칸마다 위의 버튼으로 볼 영상(RGB·IR·Depth)을 고릅니다. IR 프로젝터가 있는 카메라는 그 버튼 왼쪽에 켜짐 상태(<code>EMIT ON</code> · <code>EMIT OFF</code>)가 나옵니다. 창 위의 <code>IR 프로젝터 (전체)</code> 토글로 모든 카메라의 IR 프로젝터를 한꺼번에 켜고 끌 수 있습니다. 시야가 가려지거나 흐리지 않은지 눈으로 확인하는 창입니다.</td></tr><tr><td><code>하단 depth 카메라 On-chip 캘리브레이션</code></td><td>하단 depth 카메라의 On-chip 캘리브레이션을 실행합니다. 아래 <a href="#on-chip">On-chip 캘리브레이션</a>을 보세요.</td></tr><tr><td><code>하단 depth 카메라 위치 보정</code></td><td>캘리브레이션 보드 판으로 하단 depth 카메라 4대의 위치를 보정합니다. 아래 <a href="#position-calibration">위치 보정</a>을 보세요.</td></tr></tbody></table><h3 id="도킹-캘리브레이션" tabindex="-1">도킹 캘리브레이션 <a class="header-anchor" href="#도킹-캘리브레이션" aria-label="Permalink to &quot;도킹 캘리브레이션&quot;">​</a></h3><p>캘리브레이션 섹션 맨 아래에 자동 도킹 정렬 파라미터가 있습니다: <code>Offset X (m)</code>, <code>Offset Y (m)</code>, <code>Req Count</code>, <code>Try Count</code>.</p><ul><li><code>다시 읽기</code> — 로봇에서 값을 다시 읽어옵니다.</li><li><code>기본값</code> — 입력칸을 출고 기본값으로 채웁니다. <code>적용</code>을 누르기 전에는 저장되지 않습니다.</li><li><code>적용</code> — 값을 로봇에 저장하고 다시 읽어 확인합니다.</li></ul><h2 id="robot-check" tabindex="-1">로봇 점검 <a class="header-anchor" href="#robot-check" aria-label="Permalink to &quot;로봇 점검 {#robot-check}&quot;">​</a></h2><p><img src="'+r+'" alt="로봇 점검 섹션"></p><p><code>로봇 점검</code>은 앉은 자세부터 걷기까지 로봇 상태를 순서대로 점검합니다. 단계마다 카드가 있고, <code>측정</code>을 누른 뒤 결과를 보고, 기준을 벗어나면 옆의 보정 버튼으로 그 자리에서 고칩니다. 보정 버튼은 측정 결과와 상관없이 로봇 상태만 맞으면 누를 수 있습니다. 기준을 벗어난 값은 카드에 <code>주의</code>로만 표시됩니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>2·4·5단계는 로봇이 스스로 움직이며, 그동안 조이스틱 입력은 무시됩니다. 시작하기 전에 로봇 주변 1 m 를 비우세요. <code>중지</code>를 누르면 점검을 멈추고 로봇이 섭니다.</p></div><h3 id="보행-점검" tabindex="-1">보행 점검 <a class="header-anchor" href="#보행-점검" aria-label="Permalink to &quot;보행 점검&quot;">​</a></h3><table tabindex="0"><thead><tr><th>단계</th><th>로봇</th><th>측정</th><th>기준</th><th>보정</th></tr></thead><tbody><tr><td>1 <code>앉음 · IMU</code></td><td>앉음</td><td>중력 크기와 자이로 편차 3초 평균</td><td>9.75 ~ 9.85 m/s², 자이로 1.0 °/s 미만</td><td><code>가속도계 보정</code>, <code>자이로 바이어스 보정</code></td></tr><tr><td>2 <code>모터 캘리브레이션 상태</code></td><td>섬</td><td>로봇이 한 다리씩 들어 무릎·피치·롤 차례로 힘을 빼고 회전자를 세 상(U·V·W)에 붙잡아 저장된 모터 캘리브레이션 기준과의 차이를 전기각으로 측정 — 가장 어긋난 값을 빼고 남은 두 값으로 판정</td><td>±6°(전기각): 둘 다 안이면 정상, 하나만 벗어나면 주의, 둘 다 벗어나면 불량</td><td><code>다시 캘리브레이션</code>(불량 관절에서 묻는 팝업)</td></tr><tr><td>3 <code>서기 · 수평</code></td><td>섬</td><td>몸통 위에 올린 물방울 수평계로 몸통을 손으로 맞춘 뒤 롤·피치 2초 평균</td><td>±0.3°</td><td><code>IMU 롤/피치 영점</code></td></tr><tr><td>4 <code>관절 통신 상태</code></td><td>섬</td><td>몸통을 좌우 최대 30°로 5번(약 10초) 비트는 동안 CAN 통신 — <code>모터별</code>: 누락 프레임 수, 최저 수신 주파수, 최대 수신 간격 / <code>채널별</code>: <code>에러 프레임</code>, <code>error-warning</code>, <code>error-passive</code>, <code>bus-off</code></td><td>수신 450 Hz 이상, 수신 간격 10 ms 이하</td><td>—</td></tr><tr><td>5 <code>제자리 걸음 · 밀림</code></td><td>섬</td><td>제자리에서 10초 걸은 뒤 다시 서서 시작 위치와 비교</td><td>앞뒤 ±10 cm 미만, 좌우 ±5 cm 미만</td><td><code>육안검사</code> → <code>관절 홈포즈 세팅</code> → <code>무게 중심 보정</code></td></tr></tbody></table><ul><li>2단계: 이 카드의 버튼은 <code>캘리브레이션 시작</code>입니다. 누르면 로봇이 세 발로 버티며 다리를 하나씩 들어 재고(다리당 약 20초), 끝나면 스스로 네 발로 돌아옵니다. 재는 동안 로봇을 건드리지 마세요. 불량으로 판정된 관절이 있으면 로봇이 그 자세에 멈추고 <code>다시 캘리브레이션</code> 할지 묻습니다. 30초 안에 고르지 않으면 캘리브레이션하지 않고 다음 관절로 넘어갑니다. 팝업에는 판정에 쓴 두 값이 함께 나옵니다. 캘리브레이션하면 그 관절을 다시 잽니다. 값이 모두 기준 안이면 팝업 제목에 모터 DQ 체크 성공이 뜨고 <code>다음 관절</code>이 주 버튼, <code>다시 캘리브레이션</code>은 그 옆에 나옵니다. 아니면 <code>다시 캘리브레이션</code>할지 <code>다음 관절</code>로 넘어갈지 다시 묻습니다. 표는 재는 동안 관절 하나를 끝낼 때마다 바로 채워집니다.</li><li>4단계: 기준을 벗어난 관절이 있으면 카드에 그 다리가 표시되고, 몸통과 그 다리 모듈 사이의 배선을 점검하라고 안내합니다. 관절끼리 누락 프레임을 비교하세요. 다른 관절은 괜찮은데 한 관절만 누락이 생기면 그 다리의 배선을 의심할 수 있습니다. <code>채널별</code>에는 다리가 붙은 CAN 채널이 그 채널의 다리와 함께 나옵니다. <code>에러 프레임</code>은 트위스트 동안 채널이 상태 변화(error-warning, error-passive, bus-off, 복귀)를 알린 횟수입니다. 이 숫자들은 참고용이며 판정에는 쓰지 않습니다. 시뮬은 CAN 계측이 없어 판정하지 않습니다.</li><li>5단계: 앞뒤로 10 cm 이상 또는 좌우로 5 cm 이상 밀리면 카드에 밀린 방향이 모두 표시되고, <code>육안검사</code> → <code>관절 홈포즈 세팅</code> → <code>무게 중심 보정</code> 순서로 진행하라고 안내합니다. 홈포즈 세팅은 캘리브레이션의 다리 마법사와 같고 앉은 상태에서만 할 수 있어, 서 있으면 <code>앉기</code> 버튼이 먼저 나옵니다.</li></ul><h3 id="카메라-점검" tabindex="-1">카메라 점검 <a class="header-anchor" href="#카메라-점검" aria-label="Permalink to &quot;카메라 점검&quot;">​</a></h3><table tabindex="0"><thead><tr><th>단계</th><th>측정</th><th>판정</th><th>보정</th></tr></thead><tbody><tr><td>1 <code>카메라 시야 · FPS</code></td><td>카메라 6대의 상태와 RGB·IR·Depth FPS 를 10초 동안</td><td>목표 FPS 의 70% 아래가 3번 이상이거나 연달아 2번이면 <code>점검 필요</code></td><td><code>카메라 기본 검사</code></td></tr><tr><td>2 <code>depth 카메라 품질</code></td><td>하단 depth 카메라마다(대당 약 2초) 화면 가운데 바닥의 depth 품질</td><td><code>정상</code>, <code>OCC 권장</code>, <code>시야 확인</code>, <code>평면 없음</code>, <code>영상 없음</code></td><td><code>On-chip 캘리브레이션</code></td></tr><tr><td>3 <code>depth 카메라 위치 정합</code></td><td>하단 depth 카메라마다 기준 면 대비 roll · pitch · z, 캘리브레이션 보드 위에서는 이웃 카메라 대비 x · y · yaw (약 4초)</td><td><code>정상</code>, <code>보정 필요</code>, <code>평면 없음</code>, <code>보드 안 보임</code>, <code>꺼짐</code></td><td><code>하단 depth 카메라 위치 보정</code></td></tr></tbody></table><p>보정 버튼은 <a href="#camera-check">캘리브레이션 › 카메라 점검 · 보정</a>과 같은 창을 엽니다.</p><ul><li>1단계: 표에 카메라마다 상태, USB 연결 속도, 스트림별 FPS 가 나옵니다. USB2 로 연결된 카메라는 판정과 별개로 케이블·포트 점검을 안내합니다. 연결 상태는 금방 바뀔 수 있어, 결과는 <code>로봇 점검</code>을 벗어나면 지워집니다.</li><li>2단계: 로봇을 평평한 바닥에 세운 채 측정합니다. 서 있어야 카메라와 바닥 사이 거리가 나오므로, 앉아 있으면 <code>측정</code>과 <code>On-chip 캘리브레이션</code>이 막히고 서기 버튼이 먼저 나옵니다. 마지막 결과는 로봇이 보관해, 다시 열어도 다시 측정할 때까지 나옵니다. 표의 지표 이름 옆 <code>?</code> 에 마우스를 올리거나 누르면 설명이 나옵니다. <ul><li><code>FILL</code> — 화면 가운데에서 depth 값이 있는 픽셀의 비율입니다. 낮으면 <code>시야 확인</code>이 나옵니다. 렌즈가 가려졌거나 로봇이 앉아 있는지 확인하세요.</li><li><code>SUBPIXEL</code> — 바닥 평면에서 벗어난 정도를 시차(px)로 잰 값으로, 스테레오 매칭 정밀도입니다. 기준보다 크면 <code>OCC 권장</code>이 나옵니다.</li><li><code>PLANE RMS</code> — 같은 벗어남을 mm 로 잰 값입니다. 거리가 멀수록 커지므로 참고용입니다.</li><li><code>평면 없음</code>은 화면 가운데에서 바닥 평면을 찾지 못한 경우입니다.</li><li><code>품질</code>은 측정한 depth 품질이고, <code>보정 결과</code>는 마지막 On-chip 캘리브레이션의 결과(<code>보정 저장</code>, <code>기존 보정 유지</code>, <code>실패</code>)입니다. 보정이 실패해도 <code>품질</code>은 바뀌지 않습니다.</li></ul></li><li>3단계: 로봇을 평평한 바닥에 세운 채 측정합니다. 2단계처럼 앉아 있으면 <code>측정</code>이 막히고 서기 버튼이 먼저 나오며, 마지막 결과는 로봇이 보관합니다. 결과는 표 두 개로 나옵니다. <ul><li><code>① 기준 면 대비 — roll · pitch · z</code> — Bottom0 · 1 · 3 을 기준 센서 Bottom2 가 본 면과 비교합니다. Bottom2 가 면을 찾지 못하면 표 아래에 빨간 글씨로 이유가 나옵니다.</li><li><code>② 이웃 카메라 대비 — x · y · yaw</code> — 이웃한 두 카메라(<code>Bottom1 ↔ Bottom2</code>, <code>Bottom3 ↔ Bottom2</code>, <code>Bottom0 ↔ Bottom1</code>)가 같은 보드를 보고 잰 위치 · 방향 차이입니다. 캘리브레이션 보드 위에서 잴 때만 나옵니다. 바닥만으로는 x · y · yaw 를 볼 수 없습니다.</li><li>표의 <code>기준</code> 행에 축마다 기준이 나오고, 기준을 넘은 값은 주황색으로 표시됩니다. 한 축이라도 넘으면 그 카메라는 <code>보정 필요</code>입니다.</li></ul></li></ul><h4 id="on-chip" tabindex="-1">On-chip 캘리브레이션 <a class="header-anchor" href="#on-chip" aria-label="Permalink to &quot;On-chip 캘리브레이션 {#on-chip}&quot;">​</a></h4><p>하단 depth 카메라의 스테레오 보정값을 카메라 스스로 다시 계산합니다. 로봇을 평평한 바닥에 세워 두고 끝날 때까지 움직이지 마세요.</p><ol><li>보정할 카메라를 고릅니다. 카메라마다 마지막 측정의 판정이 함께 나오고, <code>OCC 권장</code>인 카메라가 미리 골라져 있습니다. 측정한 적이 없으면 4대가 모두 골라져 있습니다.</li><li><code>캘리브레이션 시작</code>을 누릅니다. 카메라마다 측정 → OCC 계산 → 적용 · 재측정을 차례로 진행합니다.</li><li>결과 표에 <code>SUBPIXEL</code>과 <code>PLANE RMS</code>의 보정 전 → 후 값과 변화율이 나옵니다. 충분히 좋아졌으면 로봇이 새 보정값을 카메라에 저장하고 <code>보정 저장</code>이, 그렇지 않으면 바로 원래 값으로 되돌리고 <code>기존 보정 유지</code>가 나옵니다.</li><li>한 번 더 보정하려면 <code>재보정</code>을 누릅니다.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>저장한 보정값은 카메라에 남아 로봇을 다시 켜도 유지됩니다. 보정이 끝날 때까지 로봇을 움직이지 마세요.</p></div><p>OCC 가 실패한 카메라는 바닥이 잘 보이는지(렌즈 가림, 로봇이 앉음) 확인한 뒤 다시 실행하세요. 창을 닫으면 <code>depth 카메라 품질</code> 카드의 표에 적용한 뒤의 값이 반영됩니다.</p><h4 id="position-calibration" tabindex="-1">위치 보정 <a class="header-anchor" href="#position-calibration" aria-label="Permalink to &quot;위치 보정 {#position-calibration}&quot;">​</a></h4><p>캘리브레이션 보드 판으로 하단 depth 카메라 4대의 위치를 보정합니다. 창 위에 <code>선행 점검</code> · <code>측정</code> · <code>보정</code> · <code>결과</code> 네 단계가 나옵니다.</p><p>판에는 캘리브레이션 보드 5장(보드 1~5)을 간격 없이 한 줄로 붙입니다. 보드 1 이 로봇 앞쪽에 오고, 보드마다 인쇄한 종이의 위쪽 변이 로봇 앞쪽을 향하게 합니다. 평평한 바닥에 로봇을 먼저 세운 뒤, 보드 위쪽이 로봇 앞쪽을 향하도록 판을 몸통 아래, 네 다리 사이에 넣습니다.</p><ol><li><code>선행 점검</code> — <code>측정 시작</code>을 누르면 로봇이 판 가운데 보드를 보고 판 가운데로 걸어가 자리를 잡습니다. 진행은 <code>보드 찾는 중</code> → <code>걷는 중</code> → <code>완료</code>로 나오고, 자리가 맞을 때까지 최대 2번 걷습니다. 판이 반대로 놓여 있으면 로봇은 걷지 않고 <code>캘리브레이션 보드가 뒤집혀 있습니다. 보드 위쪽이 로봇 앞쪽을 향하게 다시 놓아 주세요.</code>가 나옵니다. 판을 돌려 놓고 다시 시작하세요. <code>정지</code>를 누르면 걷기를 멈추고 섭니다. 자리를 잡으면 측정이 이어서 시작됩니다.</li><li><code>측정</code> — 카메라 4칸과 위의 표 두 개가 나옵니다. 보드가 충분히 보이지 않는 카메라가 있으면 로봇을 판 가운데로 옮긴 뒤 <code>다시 측정</code>을 누르세요. 모두 정상이면 보정할 필요가 없습니다. <code>보정 필요</code>가 있으면 <code>보정 시작</code>을 누릅니다.</li><li><code>보정</code> — 기준 센서 Bottom2 에 이웃 카메라를 차례로 맞춥니다. Bottom2 는 이 보정으로 바꾸지 않습니다.</li><li><code>결과</code> — 보정한 뒤 다시 재서 4대 모두 정상이면 보정을 남기고 <code>보정했습니다</code>가, 아니면 4대를 모두 보정 전으로 되돌리고 <code>보정하지 않고 되돌렸습니다</code>가 나옵니다. 고칠 것이 없었으면 <code>이미 정상입니다</code>가 나옵니다. 보정을 남긴 뒤에도 <code>보정 전으로 되돌리기</code>로 직전 값으로 돌아갈 수 있습니다. 되돌려졌을 때는 판이 밀리지 않았는지 확인하고 <code>다시 보정</code>을 누르세요.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>선행 점검</code> 동안 로봇이 스스로 걷습니다. 시작하기 전에 로봇 주변을 비우세요. 그 뒤로는 끝날 때까지 로봇과 판을 움직이지 마세요.</p></div><p><code>보정 전으로 되돌리기</code>는 비전을 다시 시작하기 전까지만 할 수 있습니다.</p><h3 id="remote-check" tabindex="-1">원격 점검 <a class="header-anchor" href="#remote-check" aria-label="Permalink to &quot;원격 점검 {#remote-check}&quot;">​</a></h3><p><code>원격 점검</code>은 <code>로봇 점검</code> 맨 아래 마지막 섹션입니다. 켜면 레인보우로보틱스 지원팀이 정한 시간 동안 밖에서 이 로봇을 점검할 수 있습니다. 지원팀은 앱으로 로봇에 붙어 상태를 보고 조작하며, SSH로는 현장 기술자와 같은 권한으로 로봇 PC를 다룹니다 — 로그를 확인하고, 설정과 소프트웨어를 고치고, 로봇 소프트웨어를 다시 시작하거나 재부팅하고, 로봇 명령을 보냅니다. 1회용 키는 로봇이 만들어 지원팀에만 전달하므로 비밀번호를 따로 정하거나 알려 줄 필요가 없습니다. 로봇이 인터넷에 연결되어 있어야 합니다 — <a href="/RBQ/nightly/ko/manual/operation/robot-internet.html">로봇을 인터넷에 연결하기</a>를 보세요. 원격 점검은 로봇에서 켜므로 앱이 로봇에 연결되어 있어야 하고, 연결되지 않았으면 이 섹션에 <code>로봇에 연결되어 있지 않습니다</code>만 표시됩니다.</p><ol><li>지원팀이 원격 점검을 켜 달라고 하면 이 섹션에서 <code>켜기 1시간</code>, <code>켜기 2시간</code>, <code>켜기 4시간</code> 중 하나를 누릅니다. 지원팀이 먼저 접속하거나 접속을 요청하는 일은 없습니다 — 직접 켰을 때만 시작됩니다.</li><li>켜지지 않으면 버튼 아래에 이유가 빨간 글씨로 나옵니다. <code>켜지 못했습니다 — 로봇이 인터넷에 연결되어 있지 않습니다</code>이면 로봇을 먼저 인터넷에 연결합니다(<a href="/RBQ/nightly/ko/manual/operation/robot-internet.html">로봇을 인터넷에 연결하기</a> 참고). <code>켜지 못했습니다 — 로봇의 SSH 서버가 꺼져 있습니다</code>이면 로봇 PC가 접속을 받을 준비가 되지 않은 것입니다 — 로봇을 껐다가 다시 켜고, 계속되면 지원팀에 문의합니다.</li><li>켜져 있는 동안 로봇에 직접 연결된 기기(원격 연결이 아닌 기기)의 모든 화면 위에 <code>원격 점검 중</code> 배너가 SSH 접속 수, 남은 시간, <code>끊기</code> 버튼과 함께 표시됩니다. 지원팀이 붙어도 제어권은 넘어가지 않습니다. 지원팀이 로봇을 조작하려고 제어권을 가져가면 이 기기는 관전이 되고 <code>레인보우 지원팀이 원격으로 조종 중 · 눌러서 제어권 가져오기</code>가 표시됩니다 — 누르면 언제든 제어권을 되찾습니다. 관전 중에도 <code>E-STOP</code>, 배너의 <code>끊기</code>, 이 섹션은 그대로 쓸 수 있습니다 — 이때 정비에는 <code>로봇 점검</code>만, 그 안에는 이 섹션만 보입니다.</li><li><code>끊기</code>를 누르면 지원팀의 앱과 SSH 접속이 바로 모두 끊기고, 지원팀이 로봇 PC에서 실행해 둔 작업도 함께 끝납니다. 시간이 다 되어도 같습니다. 다음에 점검하려면 다시 켜야 합니다.</li></ol><p>켜기·끊기와 접속은 모두 어디서 왔는지와 함께 로봇 시스템 로그에 남습니다. 로봇이 아직 원격 연결에 등록되지 않았으면 <code>켜기</code> 버튼을 누를 때 먼저 레인보우 서버에 등록할지 묻습니다(<code>원격 등록</code>). <code>등록</code>을 누르고 — 등록만으로는 아무도 접속할 수 없습니다 — PC를 켜 둔 채 로봇 소프트웨어만 다시 시작하는 <code>로봇 서비스 재시작</code>이나 <code>로봇 PC 재부팅</code>을 누른 뒤(로봇이 서 있으면 둘 다 눌리지 않으니 먼저 앉힙니다. <code>로봇 서비스 재시작</code>이 실패하면 <code>로봇 PC 재부팅</code>을 씁니다), 로봇이 다시 켜지면 원격 점검을 다시 켭니다. 이때 폰에 인터넷이 필요합니다. 로봇이 인터넷에 연결되어 있으면 로봇을 거쳐 닿습니다(<a href="/RBQ/nightly/ko/manual/operation/robot-internet.html">로봇을 인터넷에 연결하기</a> 참고). 등록하지 않으려면 <code>취소</code>를 누릅니다. 설정 일부만 빠졌으면 이 섹션이 무엇이 빠졌는지 보여 주고(예: <code>원격 접속이 꺼져 있습니다(enabled)</code>, <code>로봇 이름이 비어 있습니다(robot_id)</code>), <code>켜기</code>를 누르면 그 값만 채울지 묻습니다(<code>채우기</code>). 채운 뒤 로봇을 다시 시작합니다. 서버에는 이미 등록됐는데 로봇의 입장권이 없어졌으면 그렇게 안내하니 지원 담당에게 다시 등록해 달라고 하세요.</p><p>앱 없이도 켜고 끊을 수 있습니다. 로봇 망에 붙은 기기의 브라우저에서 <code>http://&lt;로봇 주소&gt;:8080</code>을 열어 로그인한 뒤 <code>Settings</code> › <code>Remote check</code>에서 <code>Turn on · 1 h</code>(2 h, 4 h)를 누릅니다. <code>Disconnect</code>로 끊습니다. 이 화면도 빠진 원격 연결 설정을 보여 주고, 등록되지 않은 로봇이면 앱과 똑같이 등록합니다(그 뒤 <code>Restart robot</code>). 이때 이 화면을 연 기기가 인터넷에 닿아야 합니다.</p><h2 id="ptz-check" tabindex="-1">PTZ 점검 <a class="header-anchor" href="#ptz-check" aria-label="Permalink to &quot;PTZ 점검 {#ptz-check}&quot;">​</a></h2><p>PTZ(카메라를 좌우 · 위아래로 돌리는 장치)가 달린 로봇에서만 보입니다. 로봇이 PTZ 의 축 · 카메라 · 소리 · 통신을 차례로 검사하고 결과를 로봇에 남깁니다. 검사는 로봇이 돌리므로 앱을 닫아도 끝까지 가고, 어느 기기에서든 진행을 보고 멈출 수 있습니다. 섹션 안에는 <code>검사</code> · <code>결과</code> 두 칸이 있습니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>검사하는 동안 PTZ 축이 끝에서 끝까지 움직이고, 카메라 스피커에서 1 kHz · 2 kHz 삐 소리가 2초씩 납니다. 축 주변을 비우세요. 주변이 시끄러우면 13단계(스피커 → 마이크)가 FAIL 날 수 있습니다. 검사하는 동안에는 PTZ 를 조작할 수 없고, 시작하기 직전 10초 안에 누가 PTZ 를 조작했다면 시작 확인 창에 경고가 뜹니다.</p></div><h3 id="검사-종류" tabindex="-1">검사 종류 <a class="header-anchor" href="#검사-종류" aria-label="Permalink to &quot;검사 종류&quot;">​</a></h3><table tabindex="0"><thead><tr><th>사용자</th><th>단추</th><th>하는 일</th></tr></thead><tbody><tr><td>모든 사용자</td><td><code>검사 시작</code></td><td>16단계, 약 2분. 전류 영점은 저장된 값을 읽어 범위만 보고, 프리셋을 바꾸는 11 · 18단계는 뺍니다</td></tr><tr><td><a href="/RBQ/nightly/ko/manual/gui/developer-mode.html">개발자 모드</a></td><td><code>기본 검사 시작</code></td><td>1~18단계. 전류 영점을 다시 재서 저장합니다. 프리셋 단계(11 · 18)는 시작할 때 동의하면 돕니다</td></tr><tr><td><a href="/RBQ/nightly/ko/manual/gui/developer-mode.html">개발자 모드</a></td><td><code>에이징 검사 시작</code></td><td>1~18단계 → 공회전(<code>30분</code> · <code>2시간</code> · <code>12시간</code>, 기본 12시간) → 재검사(20) 뒤 최종 보고. 공회전 동안 PITCH 전류를 3 A 로 잠시 낮추고 끝나면 풉니다</td></tr></tbody></table><p>3단계(<code>펌웨어 최신화</code>)는 지금은 건너뛰고 <code>기준 펌웨어가 로봇에 없어 건너뜀</code>으로 표시됩니다 — 기준 펌웨어가 아직 로봇 소프트웨어에 실리지 않습니다.</p><p>에이징 검사에서 1~18단계에 FAIL 이 있으면 공회전으로 넘어가기 전에 <code>여기서 종료</code> · <code>에이징 진행</code>을 묻습니다. 10분 동안 답이 없으면 종료합니다. 계속하면 최종 보고서에 FAIL 로 남습니다.</p><p>진행하는 동안 <code>검사</code> 칸에는 단계 표와 PTZ 의 지금 각도가, 공회전 동안에는 전류 그래프와 지금까지 상태(위치 신호 · 명령과 위치 차이 · 통신 응답 시간 · 카메라 영상)가 나옵니다. <code>중지</code>를 누르면 검사가 멈추고 결과는 <code>무효</code>로 남습니다. 로봇 배터리가 10 % 이하로 내려가거나 검사 중에 전원이 끊겨도 <code>무효</code>로 남습니다.</p><h3 id="결과" tabindex="-1">결과 <a class="header-anchor" href="#결과" aria-label="Permalink to &quot;결과&quot;">​</a></h3><p><code>결과</code> 칸은 이 로봇에서 한 PTZ 검사를 최근 20건까지 보여 줍니다. 새 검사가 생기면 가장 오래된 것부터 지웁니다. 줄을 누르면 보고서가 열립니다 — 판정, 검사 결과 표, 주요 수치, 단계마다 무엇을 · 어떻게 · 왜 재는지와 기준, 공회전 그래프, 재검사 비교가 들어 있습니다. 녹화(30초)는 로봇과 같은 망에 붙었을 때만 볼 수 있습니다.</p><table tabindex="0"><thead><tr><th>판정</th><th>뜻</th></tr></thead><tbody><tr><td><code>PASS</code></td><td>정상입니다</td></tr><tr><td><code>WARN</code></td><td>확인 필요 — 사용은 가능합니다. 다음 점검 때 지원팀과 확인하세요</td></tr><tr><td><code>FAIL</code></td><td>지원팀에 문의하세요</td></tr><tr><td><code>무효</code></td><td>검사를 끝까지 하지 못했습니다(중지 · 배터리 · 전원 끊김). 제품 판정이 아니니 다시 검사하세요</td></tr></tbody></table><p>가장 최근 검사 줄에는 <code>단계 다시</code>가 있습니다. 1~18단계 가운데 고른 단계만 다시 돌리며, 혼자 돌 수 없는 단계에 필요한 준비 단계(1 · 2 · 17 등)가 같이 돕니다. 처음 결과는 지워지지 않고, 처음 FAIL 이었던 단계는 다시 돌려 PASS 가 나와도 종합이 <code>WARN</code> 까지만 올라갑니다. 검사가 끝난 뒤 아직 보지 않은 결과가 있으면 허브의 <code>정비</code> 타일에 점이 뜹니다.</p><h2 id="vision" tabindex="-1">비전 <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;비전 {#vision}&quot;">​</a></h2><p><img src="'+l+'" alt="비전 섹션"></p><p>야간 모드·스텔스·IR 프로젝터·영상 해상도 같은 비전 토글은 제어 화면의 <code>비전</code> 팝오버에 있습니다. <a href="/RBQ/nightly/ko/manual/gui/camera-vision.html">카메라 · 비전</a>을 보세요. 이 섹션에는 개발자용 도구가 있습니다.</p><p><code>카메라 캘리브레이션</code>:</p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>Jig Extrinsic 보정</code></td><td>지그 마커로 센서마다 base↔센서 변환을 보정합니다. 로봇이 캘리브 지그에 올바르게 안착되어 있어야 합니다. 결과는 HAL 설정에 기록됩니다.</td></tr><tr><td><code>OAK-D Intrinsic 보정</code></td><td>걸으면서 전방·후방 스테레오 카메라를 보정합니다. 전방 카메라가 1 m 이내에서 ChArUco 보드를 향해야 합니다. 결과는 각 카메라의 EEPROM 에 기록됩니다.</td></tr></tbody></table><p><code>실행</code>을 누르면 시작 전에 확인할 것을 보여 주는 창이 뜨고, 진행 상황과 결과는 상단 배너에 나옵니다. 보정이 도는 동안에는 두 버튼이 <code>취소</code>로 바뀝니다.</p><p><code>OAK-D Intrinsic 보정</code> 창은 맨 위 단계 줄(<code>선행 점검</code> → <code>보드 접근</code> → <code>촬영</code> → <code>계산·기록</code> → <code>결과</code>)을 따라 진행됩니다. <code>선행 점검</code>에서 <code>보행 모드</code>를 <code>RL Walk</code>·<code>Wave</code>·<code>Stairs</code> 중에서 고르고 <code>시작</code>을 누릅니다. 창을 열 때마다 족형 로봇은 <code>RL Walk</code>, 휠 로봇은 <code>Stairs</code>로 돌아갑니다. 시작한 뒤에도 창은 열려 있고, <code>촬영</code>에서는 전방 카메라·후방 카메라마다 보드 접근부터 180° 회전까지 어디를 지나고 있는지 보여 줍니다. <code>결과</code>에는 전방·후방 OAK-D 각각의 성공·실패가 나옵니다. 창을 닫아도 로봇은 계속하며, 그때만 상단 배너가 뜨고 배너를 누르면 창이 다시 열립니다. 도중에 멈추려면 <code>정지</code>를 누릅니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>OAK-D 내부 파라미터 보정은 로봇이 약 10분간 스스로 걸어 다닙니다. 시작하기 전에 로봇 주변 1.5 m 를 비우세요.</p></div><p><code>데몬 제어</code> — <code>VISION RESET</code> → <code>리셋</code>을 누르면 Handler가 로봇이 늘 띄워 두는 비전 데몬을 모두 다시 시작합니다. Handler가 들어 있는 <code>Vision</code>만 빼고 <code>HAL</code>, <code>Streamer</code> 등 전부입니다. HAL이 시작하면서 카메라 전원을 껐다 켜므로, 카메라와 Streamer가 다시 올라올 때까지 영상이 끊깁니다. 버튼은 <code>리셋 중…</code>으로 바뀌어 약 8초 동안 비활성화됩니다.</p><p><code>Vision Programs</code>에서는 비전 데몬(<code>Vision</code>, <code>HAL</code>, <code>Streamer</code>, <code>Handeye</code>, <code>Heightmap</code>, <code>Ptz</code>)을 하나씩 수동으로 시작·정지할 수 있습니다. 켜짐/꺼짐 표시는 로봇이 보고한 프로그램 상태를 따르며, 상태를 보고하지 않는 구형 데몬에서만 마지막으로 보낸 명령 기준으로 표시합니다. <code>정지</code>를 눌러도 데몬은 꺼진 채로 남지 않습니다. 기본 설정에서는 여섯 개 모두 로봇이 몇 초 안에 다시 띄웁니다. 재부팅 없이 바뀐 설정을 반영할 때 이렇게 씁니다. 예를 들어 <code>Streamer.ini</code>의 RTSP 설정을 고친 뒤에는 <code>Streamer</code>를 한 번 누르세요. Streamer가 다시 시작하는 동안 앱 영상이 몇 초 끊깁니다. <code>HAL</code>을 정지하면 <code>VISION RESET</code>처럼 카메라 전원을 껐다 켜므로, 카메라가 다시 올라올 때까지 영상이 끊깁니다.</p><h2 id="config-file" tabindex="-1">설정 파일 <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;설정 파일 {#config-file}&quot;">​</a></h2><p><img src="'+n+'" alt="설정 파일 섹션"></p><p>INI 에디터는 로봇 데몬의 설정 파일을 직접 편집합니다. 위쪽 토글로 <code>Motion.ini</code>, <code>HAL · config.ini</code>, <code>Handler · config.ini</code>, <code>Streamer.ini</code>를 켜고 끕니다. 여러 개를 켜면 차례로 이어서 보입니다. <code>키·값·섹션 검색</code>은 켠 파일 전체에서 찾고, 걸린 섹션만 펼칩니다. 섹션은 접힌 채로 시작합니다. 섹션을 눌러 펼치거나 <code>모두 펼치기</code>·<code>모두 접기</code>를 씁니다. <code>바꾼 것만</code>은 고친 키만 보여 줍니다. 내려도 검색 줄은 위에 남습니다. 불리언 값은 토글로, 나머지 값은 그 자리에서 편집합니다. 파일마다 머리에 읽어 온 섹션 수와 시각이 표시됩니다.</p><p><code>Motion.ini</code>에서 로봇의 모델 값(감속비, 링크 질량, 한계값)은 로봇 소프트웨어에 내장된 플랫폼 프로필에서 오며, 에디터는 그 키를 흐리게 표시합니다. 값을 고쳐 저장하면 이 로봇의 덮어쓰기로 <code>Motion.ini</code>에 저장되고 그 키가 강조됩니다. 덮어쓴 키 옆의 <code>기본값으로</code> 버튼은 프로필 값을 되돌려 넣으며, 프로필과 같은 값으로 저장하면 그 키는 파일에서 지워집니다.</p><p>하단에 저장하지 않은 변경 수(<code>변경 {n}개</code>)가 표시됩니다. <code>되돌리기</code>는 변경을 버리고, <code>다시 읽기</code>는 켠 파일을 로봇에서 다시 읽어오며, <code>저장</code>은 바뀐 키마다 이전 값과 새 값을 나열하는 확인 창 <code>{label}에 저장하시겠습니까?</code>(여러 파일을 고쳤으면 <code>설정 파일 {n}개에 저장하시겠습니까?</code>)을 엽니다.</p><p>로봇은 이 파일들을 그 프로그램이 켜질 때만 읽습니다. 그래서 <code>저장하고 다시 시작</code>은 파일을 저장한 뒤 그 프로그램을 다시 시작합니다.</p><ul><li><code>Motion.ini</code>, <code>Handler · config.ini</code>: PC는 켜 둔 채 로봇 소프트웨어를 다시 시작합니다. 잠시 앱과 로봇의 연결이 끊깁니다.</li><li><code>HAL · config.ini</code>, <code>Streamer.ini</code>: HAL이나 Streamer만 다시 시작합니다. 돌아올 때까지 영상이 멈춥니다.</li><li><code>Streamer.ini</code>의 <code>[BlackBox]</code> 섹션만 고쳤으면 바로 반영되어 다시 시작하지 않습니다.</li></ul><p>로봇이 앉아 있거나 제어가 꺼져 있을 때만 저장할 수 있습니다. 그렇지 않으면 확인 창에 <code>로봇을 앉히거나 제어를 끈 뒤에 저장할 수 있습니다 (지금 {gait})</code>가 표시됩니다. 로봇 소프트웨어를 다시 시작하려면 이 기기가 제어권도 가지고 있어야 합니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>저장하면 로봇의 파일 <strong>전체</strong>가 에디터의 내용으로 교체됩니다. 항상 방금 읽어 온 파일 위에서 편집하세요. 비전 PC가 따로 있는 로봇에서는 앱이 Vision을 다시 시작할 수 없습니다. <code>Handler · config.ini</code>를 저장하면 앱이 그렇게 알려 주며, 변경은 비전 PC를 다시 시작한 뒤에 반영됩니다. 의미를 모르는 값은 바꾸지 마세요.</p></div><h2 id="팔" tabindex="-1">팔 <a class="header-anchor" href="#팔" aria-label="Permalink to &quot;팔&quot;">​</a></h2><p>로봇이 팔을 보고할 때만 표시됩니다. 이 섹션은 최초 기동용입니다.</p><ol><li><code>CAN 체크</code>, <code>브레이크 해제</code>, <code>제어 시작</code>을 순서대로 누릅니다. 각 단계 후 상태 배지가 켜지는 것을 확인한 뒤 다음을 누르세요. ▶ Auto Start ARM은 이 시퀀스 전체를 한 번에 실행합니다.</li><li><code>정적 자세</code>는 궤적 없이 고정 자세(<code>Straight</code>, <code>Folding</code>, <code>Ready</code>, <code>Lift</code>, <code>Packing</code>, <code>DoorReady</code>)를 보냅니다. 첫 사용은 <code>Ready</code>부터 시작하세요.</li><li><code>관절 잠금 / 조그</code> — 관절 카드를 탭해 잠금/해제하고, 잠긴 관절은 <code>+</code> / <code>−</code>를 길게 눌러 조그합니다(잠금 해제 상태에서는 버튼이 비활성화됩니다).</li></ol>',102)])])}const A=c(h,[["render",p]]);export{S as __pageData,A as default};
